    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    def rot(vals, k):
        return vals[k:] + vals[:k]
    tests = [fmt([7]), fmt([1, 2]), fmt([2, 1]), fmt([1, 2, 3, 4, 5]), fmt([5, 1, 2, 3, 4]), fmt([2, 3, 4, 5, 1]), fmt([9, -4, 0])]
    for _ in range(16):
        n = rng.randint(1, 12)
        vals = sorted(rng.sample(range(-30, 31), n))
        tests.append(fmt(rot(vals, rng.randint(0, n - 1))))
    N = 100000
    for k in (0, N // 2, N - 1):
        vals = sorted(rng.sample(range(-500000, 500001), N))
        tests.append(fmt(rot(vals, k)))
    vals = sorted(rng.sample(range(-500000, 500001), 50000))
    tests.append(fmt(rot(vals, 31337)))
    return tests

